export function isBrandIcon(name: RailIconName): name is BrandIconName {
  return name in BRAND_ICONS;
}

/**
 * Visible label → icon. Matched on the normalised label (lower case, trailing
 * ellipsis dropped). Prefix rules cover families such as "New …".
 */
const EXACT: Record<string, RailIconName> = {
  export: "download",
  "export csv": "download",
  download: "download",
  cancel: "x",
  close: "x",
  dismiss: "x",
  "clear search": "x",
  "clear filters": "x",
  clear: "x",
  create: "check",
  save: "check",
  done: "check",
  confirm: "check",
  apply: "check",
  vault: "folder",
  "open vault": "folder",
  "check again": "refresh",
  "try again": "refresh",
  retry: "refresh",
  refresh: "refresh",
  change: "pencil",
  edit: "pencil",
  rename: "pencil",
  delete: "trash",
  remove: "trash",
  "open in claude code": "claude-code",
  "open in codex": "codex",
  "grok build": "grok",
  "open in grok build": "grok",
  invite: "user-plus",
  "invite member": "user-plus",
  "add integration": "plug",
  connect: "plug",
  copy: "copy",
  "copy link": "link",
  open: "external",
  view: "eye",
  upload: "upload",
  send: "send",
  start: "play",
  stop: "stop",
  back: "arrow-left",
  continue: "arrow-right",
  next: "arrow-right",
  "sign out": "logout",
  archive: "archive",
  unarchive: "archive",
  reject: "ban",
  choose: "check-circle",
  "select all": "check-circle",
  knock: "bell",
  enable: "bell",
  manage: "sliders",
  "more options": "sliders",
  "check for updates": "refresh",
  "check all updates": "refresh",
  "restart to update": "refresh",
  install: "download",
  "download & install": "download",
  reply: "send",
  share: "link",
  "sign in": "key",
};

const PREFIX: Array<[string, RailIconName]> = [
  ["new ", "plus"],
  ["add ", "plus"],
  ["create ", "check"],
  ["save ", "check"],
  ["export ", "download"],
  ["open in claude", "claude-code"],
  ["open in codex", "codex"],
  ["open the door", "door"],
  ["open my door", "door"],
  ["open ", "external"],
  ["clear ", "x"],
  ["delete ", "trash"],
  ["remove ", "trash"],
  ["invite ", "user-plus"],
  ["connect ", "plug"],
  ["edit ", "pencil"],
  ["change ", "pencil"],
  ["manage ", "sliders"],
  ["show in ", "folder"],
  ["attach ", "link"],
];

export function normaliseLabel(label: string): string {
  return label.trim().toLowerCase().replace(/[.…]+$/u, "").replace(/\s+/gu, " ");
}

export function iconForLabel(label: string): RailIconName | null {
  const key = normaliseLabel(label);
  if (key in EXACT) return EXACT[key];
  for (const [prefix, icon] of PREFIX) if (key.startsWith(prefix)) return icon;
  return null;
}
